          {
            "title": "Paso 7. Volver a x",
            "body": "<div class=\"math-region\" tabindex=\"0\" role=\"region\" aria-label=\"Expresión matemática. e4, Paso 7. Volver a x. 1\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\" lang=\"es\"><mrow><mrow><mi mathvariant=\"normal\">ln</mi></mrow><mo>|</mo><mn>1</mn><mo>+</mo><msup><mi>e</mi><mi>x</mi></msup><mo>|</mo><mo>+</mo><mi>C</mi></mrow></math></div>"
          },
          {
            "title": "Paso 8. Usar que el argumento es positivo",
            "body": "<div class=\"math-region\" tabindex=\"0\" role=\"region\" aria-label=\"Expresión matemática. e4, Paso 8. Usar que el argumento es positivo. 1\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\" lang=\"es\"><mrow><mrow><mi mathvariant=\"normal\">ln</mi></mrow><mrow><mo>(</mo><mn>1</mn><mo>+</mo><msup><mi>e</mi><mi>x</mi></msup><mo>)</mo></mrow><mo>+</mo><mi>C</mi></mrow></math></div>"
          }
